async function fleetAction(action,deviceIds,value=null){
  const results=await request('/api/devices/'+action.toLowerCase(),{method:'POST',body:{deviceIds,value}});
  const failures=deviceIds.map(id=>({id,result:Array.isArray(results)?results.find(item=>item.deviceId===id):null})).filter(item=>item.result?.success!==true);
  if(failures.length)throw new Error(failures.map(item=>(state.paired.find(device=>device.deviceId===item.id)?.deviceName||item.id)+': '+(item.result?.reason||item.result?.code||tr('publishResultMissing'))).join('; '));
  return results;
}
