function updatePreviewBase(){const preview=$('contentPreview');preview.innerHTML='';const type=state.selectedType;let node;if(type==='TEXT'){node=document.createElement('div');node.className='text-preview';node.textContent=$('textContent')?.value||tr('previewEmpty');node.style.fontSize=Math.min(72,Math.max(8,Number($('textSize')?.value)||48))+'px';node.style.color=$('textColor')?.value||'#fff';preview.style.background=$('textBackground')?.value||'#000';node.style.fontFamily={SYSTEM_SERIF:'serif',MONOSPACE:'monospace',MA_SHAN_ZHENG:'cursive',ZCOOL_XIAOWEI:'serif'}[$('textFont')?.value]||'system-ui'}else if((type==='IMAGE'||type==='VIDEO')&&state.mediaSource==='LOCAL'&&state.previewUrls.length){node=document.createElement(type==='VIDEO'?'video':'img');node.src=state.previewUrls[0];if(type==='VIDEO'){node.controls=true;node.muted=true}applyMediaPreviewFit(node)}else if((type==='IMAGE'||type==='VIDEO')&&state.mediaSource==='URL'&&$('mediaUrls').value.trim()){node=document.createElement(type==='VIDEO'?'video':'img');node.src=$('mediaUrls').value.trim().split(/\r?\n/)[0];if(type==='VIDEO'){node.controls=true;node.muted=true}applyMediaPreviewFit(node)}else if(type==='HTML'){preview.classList.add('html-preview-wrap');node=document.createElement('iframe');node.className='html-frame';node.sandbox='';node.title='HTML preview';node.srcdoc=$('htmlContent').value}else{node=document.createElement('div');node.className='preview-empty';node.textContent=tr('previewEmpty')}if(type!=='HTML')preview.classList.remove('html-preview-wrap');preview.appendChild(node)}
function escapeDesign(value){return String(value||'').replace(/[&<>'"]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[char]))}function designRows(){return $('designItems').value.split(/\r?\n/).map(line=>line.trim()).filter(Boolean).slice(0,24).map(line=>{const [label,...detail]=line.split('|');return '<div class="row"><b>'+escapeDesign(label.trim())+'</b><span>'+escapeDesign(detail.join('|').trim())+'</span></div>'}).join('')||'<div class="row"><b>招牌内容</b><span>说明</span></div>'}function generatedDesignHtml(){const type=$('designType').value,title=escapeDesign($('designTitle').value.trim()||'Local Signage'),subtitle=escapeDesign($('designSubtitle').value.trim()),accent=$('designAccent').value,background=$('designBackground').value,rows=designRows(),common='<style>html,body{margin:0;width:100%;height:100%;overflow:hidden}*{box-sizing:border-box}body{font-family:system-ui,-apple-system,"Segoe UI","Microsoft YaHei",sans-serif;background:'+background+';color:#fff}.page{min-height:100vh;padding:6vw}.eyebrow{color:'+accent+';font-weight:800;letter-spacing:.18em;font-size:2vw}.title{font-size:7vw;line-height:1.05;margin:1vw 0}.subtitle{font-size:2.3vw;opacity:.82}.rows{display:grid;gap:1.15vw;margin-top:4vw}.row{display:grid;grid-template-columns:1fr auto;gap:2vw;align-items:center;border-bottom:1px solid rgba(255,255,255,.25);padding:1.1vw 0;font-size:2.5vw}.row b{font-size:2.8vw}.row span{color:'+accent+';font-weight:800}</style>';if(type==='WELCOME')return '<main class="page" style="display:grid;place-content:center;text-align:center;background:'+background+'">'+common+'<div class="eyebrow">WELCOME</div><h1 class="title">'+title+'</h1><p class="subtitle">'+subtitle+'</p></main>';if(type==='PROMOTION')return '<main class="page" style="display:grid;grid-template-columns:1.2fr .8fr;align-items:center">'+common+'<section><div class="eyebrow">LIMITED OFFER</div><h1 class="title">'+title+'</h1><p class="subtitle">'+subtitle+'</p></section><section class="rows">'+rows+'</section></main>';if(type==='SCHEDULE')return '<main class="page">'+common+'<div class="eyebrow">MEETING SCHEDULE</div><h1 class="title">'+title+'</h1><p class="subtitle">'+subtitle+'</p><section class="rows">'+rows+'</section></main>';return '<main class="page">'+common+'<div class="eyebrow">TODAY MENU</div><h1 class="title">'+title+'</h1><p class="subtitle">'+subtitle+'</p><section class="rows">'+rows+'</section></main>'}function updatePreview(){if(state.selectedType!=='DESIGN')return updatePreviewBase();const preview=$('contentPreview');preview.innerHTML='';preview.classList.add('html-preview-wrap');const frame=document.createElement('iframe');frame.className='html-frame';frame.sandbox='';frame.title='Offline design preview';frame.srcdoc=generatedDesignHtml();preview.appendChild(frame)}
async function uploadWebPackage(){const file=$('webPackage').files[0];if(!file)return null;const form=new FormData();form.append('file',file,file.name);const response=await fetch('/api/resources/web-package',{method:'POST',headers:apiHeaders(),body:form});const raw=await response.text();const data=raw?JSON.parse(raw):null;if(!response.ok){const error=new Error(data?.error?.message||tr('requestFailed'));error.code=data?.error?.code;throw error}return data}
function uploadMedia(shouldPlay=true){
  if(!state.selectedFiles.length)return Promise.reject(new Error(tr('chooseFiles')));
  const form=new FormData();
  form.append('play',String(shouldPlay));
  form.append('fitMode',$('fitMode').value);
  form.append('cropGravity',$('fitMode').value==='CROP'?$('cropGravity').value:'CENTER');
  if(state.selectedType==='IMAGE'){
    form.append('durationMs',String(Number($('imageDuration').value)*1000));
    form.append('transitionEffect',$('imageTransition').value);
  }else form.append('playbackSpeed',$('videoSpeed').value);
  state.selectedFiles.forEach(file=>form.append('file',file,file.name));
  return new Promise((resolve,reject)=>{
    const xhr=new XMLHttpRequest();
    state.uploadRequest=xhr;
    state.uploadCanCancel=true;
    renderSendActions();
    xhr.open('POST','/api/resources/upload');
    Object.entries(apiHeaders()).forEach(([name,value])=>xhr.setRequestHeader(name,value));
    xhr.setRequestHeader('Accept','application/json');
    xhr.upload.addEventListener('progress',event=>{
      if(!event.lengthComputable)return setSendStatus(tr('preparingContent'));
      const percent=Math.min(99,Math.round(event.loaded/event.total*100));
      setSendStatus(tr('uploading',{percent,sent:formatBytes(event.loaded),total:formatBytes(event.total)}),percent);
    });
    xhr.upload.addEventListener('load',()=>{
      state.uploadCanCancel=false;
      setSendStatus(tr('processingUpload'),100);
      renderSendActions();
    });
    xhr.addEventListener('load',()=>{try{resolve(xhrResponse(xhr))}catch(error){reject(error)}});
    xhr.addEventListener('error',()=>reject(new Error(tr('networkFailed'))));
    xhr.addEventListener('abort',()=>{const error=new Error(tr('uploadCancelled'));error.cancelled=true;reject(error)});
    xhr.addEventListener('loadend',()=>{if(state.uploadRequest===xhr){state.uploadRequest=null;state.uploadCanCancel=false;renderSendActions()}});
    xhr.send(form);
  });
}
async function sendContent(){
  if(state.sendInProgress)return;
  const target=state.activeTarget||$('sendTargetSelect')?.value||'LOCAL';
  const targetDevices=PublishWorkflow.targets(target,{deviceId:state.current?.deviceId,deviceName:state.current?.deviceName||tr('thisDevice')},state.paired);
  if(!targetDevices.length)return notify(tr('publishTargetMissing'),true);
  setSendBusy(true);
  try {
    if(!state.owner)await acquire(true);
    if(!state.owner){setSendBusy(false);return notify(tr('takeControl'),true)}
  }catch(error){setSendBusy(false);return notify(describeError(error),true)}
  // 先保存内容，再按固定目标发布，分组永远不隐式包含网关本机。
  const shouldPlayLocal=false;
  const type=state.selectedType,name=$('contentName').value.trim()||undefined;
  state.sendFailed=false;
  setSendStatus(tr('preparingContent'));
  setSendBusy(true);
  try{
    let response;
    if(type==='TEXT'){
      const content=$('textContent').value.trim();
      if(!content)throw new Error(tr('enterText'));
      response=await request('/api/resources/virtual',{method:'POST',body:{name,kind:'TEXT',content,textSizeSp:Number($('textSize').value),textColor:$('textColor').value,textBackgroundColor:$('textBackground').value,fontFamily:$('textFont').value,textSpeedDpPerSecond:Number($('textSpeed').value),play:shouldPlayLocal}});
    }else if(type==='IMAGE'||type==='VIDEO'){
      if(state.mediaSource==='LOCAL'){
        response=await uploadMedia(shouldPlayLocal);
      }else{
        const urls=$('mediaUrls').value.split(/\r?\n/).map(value=>value.trim()).filter(Boolean);
        if(!urls.length)throw new Error(tr('enterUrl'));
        response=await request('/api/resources/link',{method:'POST',body:{name,mediaType:type,urls,fitMode:$('fitMode').value,cropGravity:type==='IMAGE'&&$('fitMode').value==='CROP'?$('cropGravity').value:'CENTER',durationMs:type==='IMAGE'?Number($('imageDuration').value)*1000:undefined,transitionEffect:type==='IMAGE'?$('imageTransition').value:undefined,playbackSpeed:type==='VIDEO'?Number($('videoSpeed').value):undefined,play:shouldPlayLocal}});
      }
    }else if(type==='STREAM'){
      const sourceUri=$('streamUrl').value.trim();
      if(!sourceUri)throw new Error(tr('enterUrl'));
      response=await request('/api/resources/virtual',{method:'POST',body:{name,kind:'STREAM',sourceUri,play:shouldPlayLocal}});
    }else if(type==='WEB'){
      const sourceUri=$('webUrl').value.trim();
      if(!sourceUri)throw new Error(tr('enterUrl'));
      response=await request('/api/resources/virtual',{method:'POST',body:{name,kind:'WEB',sourceUri,refreshIntervalMs:Number($('webRefresh').value)?Number($('webRefresh').value)*1000:undefined,play:shouldPlayLocal}});
    }else if(type==='DESIGN'){
      const content=generatedDesignHtml();
      response=await request('/api/resources/virtual',{method:'POST',body:{name:name||$('designTitle').value.trim()||'Offline design',kind:'WEB',content,play:shouldPlayLocal}});
    }else{
      if(state.h5Source==='PACKAGE'){
        if(!$('webPackage').files.length)throw new Error(tr('chooseH5Package'));
        response=await uploadWebPackage();
      }
      else{const content=$('htmlContent').value.trim();if(!content)throw new Error(tr('enterHtml'));if(htmlBlocked(content))throw new Error(tr('unsupportedHtml'));response=await request('/api/resources/virtual',{method:'POST',body:{name:name||'HTML',kind:'WEB',content,play:shouldPlayLocal}});}
    }

    const createdResourceId=response?.id||(Array.isArray(response?.ids)?response.ids[0]:null);
    const createdPlaylistId=response?.playlistId;
    publicationJob=PublishWorkflow.create({resourceId:createdResourceId,playlistId:createdPlaylistId},targetDevices);
    renderPublicationResults();
    await runPublication();
  }catch(error){
    state.sendFailed=!error.cancelled;
    const keepsFiles=(type==='IMAGE'||type==='VIDEO')&&state.mediaSource==='LOCAL'&&state.selectedFiles.length>0;
    const reason=error.cancelled?tr('uploadCancelled'):describeError(error);
    const message=error.cancelled?tr('uploadCancelled'):tr(keepsFiles?'sendFailedRetry':'sendFailed',{reason});
    setSendStatus(message,null,!error.cancelled);
    if(!error.cancelled)notify(reason,true);
  }finally{
    setSendBusy(false);
    renderPublicationResults();
  }
}
async function loadDevices(){try{const [discovered,paired,fleet,assignments]=await Promise.all([request('/api/devices'),request('/api/devices/paired'),request('/api/devices/status'),request('/api/device-assignments')]);state.discovered=discovered||[];state.paired=paired||[];state.fleet=fleet||[];state.assignments=assignments||[];renderDevices();updateGlobalTargetOptions()}catch(error){notify(describeError(error),true)}}
function assignmentFor(deviceId){return state.assignments.find(item=>item.deviceId===deviceId)}function assignmentStatus(assignment){if(!assignment)return {key:'noAssignment',className:'offline'};if(assignment.state==='SYNCED')return {key:'assignmentSynced',className:'online'};if(assignment.state==='FAILED')return {key:'assignmentFailed',className:'failed'};return {key:'assignmentPending',className:'pending'}}function renderDevices(){const list=$('deviceList');list.innerHTML='';const local={deviceId:state.current?.deviceId,deviceName:state.current?.deviceName||'Local Signage',host:location.hostname,port:location.port,status:'ONLINE',playing:!!state.current?.playing,currentResourceId:state.current?.currentResourceId,currentResourceName:state.current?.currentResourceName,local:true};const devices=[local,...state.paired.map(item=>({...item,...(state.fleet.find(value=>value.deviceId===item.deviceId)||{}),status:state.fleet.find(value=>value.deviceId===item.deviceId)?.state||'OFFLINE'}))];$('deviceTotal').textContent=devices.length;$('deviceOnline').textContent=devices.filter(item=>item.local||item.status==='ONLINE').length;$('devicePlaying').textContent=devices.filter(item=>item.playing).length;$('deviceIssues').textContent=devices.filter(item=>!item.local&&(item.status!=='ONLINE'||assignmentFor(item.deviceId)?.state==='FAILED')).length;$('deviceUpdated').textContent=tr('updated',{time:formatDateTime(Date.now(),{timeStyle:'short'})});devices.forEach(item=>{const assignment=assignmentFor(item.deviceId),assignmentView=assignmentStatus(assignment);const row=document.createElement('div');row.className='device-row';const main=document.createElement('div'),title=document.createElement('div');title.className='device-title';const strong=document.createElement('strong');strong.textContent=item.deviceName;const chip=document.createElement('span');chip.className='status-chip '+((item.local||item.status==='ONLINE')?'online':'offline');chip.textContent=item.local?tr('thisDevice'):tr(item.status==='ONLINE'?'online':'deviceOffline');title.append(strong,chip);if(!item.local&&assignment){const assignmentChip=document.createElement('span');assignmentChip.className='status-chip '+assignmentView.className;assignmentChip.textContent=tr(assignmentView.key);title.appendChild(assignmentChip)}const meta=document.createElement('div');meta.className='device-meta';const address=document.createElement('span');address.textContent=(item.host||location.hostname)+':'+(item.port||location.port);const content=document.createElement('span');content.textContent=tr('currentContent')+': '+(item.currentResourceName||resourceName(item.currentResourceId));meta.append(address,content);if(!item.local&&item.groupName){const group=document.createElement('span');group.textContent=tr('deviceGroup')+': '+item.groupName;meta.appendChild(group)}if(!item.local&&assignment?.lastSyncAt){const synced=document.createElement('span');synced.textContent=tr('lastSynced',{time:formatDateTime(assignment.lastSyncAt)});meta.appendChild(synced)}main.append(title,meta);const btns=document.createElement('div');btns.style.display='flex';btns.style.gap='8px';const switchBtn=document.createElement('button');switchBtn.className='primary';switchBtn.textContent=tr('switchToControl');switchBtn.addEventListener('click',()=>{state.activeTarget=item.local?'LOCAL':('DEVICE_'+item.deviceId);updateGlobalTargetOptions();showView('playback')});const manage=document.createElement('button');manage.textContent=tr('manage');manage.addEventListener('click',()=>item.local?openLocalSettings():openRemoteDevice(item.deviceId));btns.append(switchBtn,manage);row.append(main,btns);list.appendChild(row)});setOwner(state.owner)}
