function syncConsoleSemantics() {
  const nav = document.querySelector('.nav');
  const language = $('language');
  if (nav) nav.setAttribute('aria-label', tr('consoleNavigation'));
  if (language) language.setAttribute('aria-label', tr('consoleLanguage'));
  document.querySelectorAll('dialog .dialog-head button[aria-label]').forEach(button => button.setAttribute('aria-label', tr('consoleClose')));

  const lists = new Set(document.querySelectorAll('[role="tablist"], .content-tabs, .h5-mode-tabs'));
  const sendPanels = { TEXT: 'textEditor', IMAGE: 'mediaEditor', VIDEO: 'mediaEditor', STREAM: 'streamEditor', WEB: 'webEditor', DESIGN: 'designEditor', HTML: 'htmlEditor' };
  lists.forEach((list, listIndex) => {
    list.setAttribute('role', 'tablist');
    const tabs = [...list.querySelectorAll('button')].filter(button => button.closest('[role="tablist"]') === list);
    const panelLabels = new Map();
    tabs.forEach((button, index) => {
      if (!button.id) button.id = `console-tab-${listIndex}-${index}`;
      button.setAttribute('role', 'tab');
      const selected = button.classList.contains('active');
      button.setAttribute('aria-selected', String(selected));
      button.tabIndex = selected ? 0 : -1;
      const panelId = button.dataset.contentTab ? `${button.dataset.contentTab}Panel` : button.dataset.sendType ? sendPanels[button.dataset.sendType] : button.dataset.h5Source ? (button.dataset.h5Source === 'PACKAGE' ? 'h5PackageSource' : 'h5CodeSource') : '';
      const panel = panelId && document.getElementById(panelId);
      if (panel) {
        button.setAttribute('aria-controls', panelId);
        if (selected || !panelLabels.has(panel)) panelLabels.set(panel, button.id);
      }
    });
    panelLabels.forEach((tabId, panel) => {
      panel.setAttribute('role', 'tabpanel');
      panel.setAttribute('aria-labelledby', tabId);
    });
  });
}
function bindConsoleKeyboard() {
  document.addEventListener('click', event => {
    const tab = event.target.closest?.('[role="tablist"] [role="tab"]');
    if (tab) syncConsoleSemantics();
    const radio = event.target.closest?.('[role="radiogroup"] [role="radio"]');
    if (radio) {
      const group = radio.closest('[role="radiogroup"]');
      group.querySelectorAll('[role="radio"]').forEach(item => item.tabIndex = item.getAttribute('aria-checked') === 'true' ? 0 : -1);
    }
  });
  document.addEventListener('keydown', event => {
    const tab = event.target.closest?.('[role="tablist"] [role="tab"]');
    if (tab && ['ArrowLeft', 'ArrowRight', 'Home', 'End'].includes(event.key)) {
      const list = tab.closest('[role="tablist"]');
      const tabs = [...list.querySelectorAll('[role="tab"]')].filter(item => item.closest('[role="tablist"]') === list && !item.disabled);
      const index = tabs.indexOf(tab);
      const direction = getComputedStyle(list).direction === 'rtl' ? -1 : 1;
      const nextIndex = event.key === 'Home' ? 0 : event.key === 'End' ? tabs.length - 1 : (index + (event.key === 'ArrowRight' ? direction : -direction) + tabs.length) % tabs.length;
      event.preventDefault();
      tabs[nextIndex]?.focus();
      tabs[nextIndex]?.click();
      return;
    }
    const radio = event.target.closest?.('[role="radiogroup"] [role="radio"]');
    if (radio && ['ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown'].includes(event.key)) {
      const group = radio.closest('[role="radiogroup"]');
      const radios = [...group.querySelectorAll('[role="radio"]')];
      const index = radios.indexOf(radio);
      const forward = event.key === 'ArrowRight' || event.key === 'ArrowDown';
      const next = radios[(index + (forward ? 1 : -1) + radios.length) % radios.length];
      event.preventDefault();
      next.focus();
      next.click();
    }
  });
}
async function init(){bind();bindContentControls();bindCropControls();bindEnhancedControls();bindConsoleKeyboard();localize();selectContentTab('resources');selectSendType('TEXT');selectMediaSource('LOCAL');try{if(issuedPairingToken){try{await exchangeAccess({pairingToken:issuedPairingToken});history.replaceState(null,'',location.pathname)}catch(error){if(!state.token)throw error}}if(!state.token){showDialog('accessDialog');await probeDevice();return}await startAuthenticated()}catch(error){showDialog('accessDialog');await probeDevice();notify(error.message,true)}}init();
